  graph,
  colors = NULL,
  sh = c("fm", "f", "fs", "fl", "flm", "fsm")
) {
  # Argument checks
  ensure_igraph(graph)
  if (is_missing(colors)) {
    if ("color" %in% vertex_attr_names(graph)) {
      colors <- V(graph)$color
